<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { tradingApi } from '../api/trading'
import PaginationBar from '../components/PaginationBar.vue'
const orders=ref<any[]>([]);const error=ref('');const message=ref('');const loading=ref(true);const blockedOrder=ref<any>(null);const page=ref(1);const pageSize=ref(10);const total=ref(0);const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
async function load(){loading.value=true;try{const r=(await tradingApi.pending(pageSize.value,(page.value-1)*pageSize.value)).data;orders.value=r.data.items;total.value=r.data.total}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}}
function changeSize(n:number){pageSize.value=n;page.value=1;load()}function go(n:number){page.value=Math.min(Math.max(n,1),pages.value);load()}
function riskBlockMessage(e:any){const detail=e?.response?.data?.detail||e?.detail;return (detail?.code||e?.code)==='RISK_CONTROL_BLOCKED'?`订单已被风控拦截：${detail?.message||e?.message||'存在未处理风险预警，请先由风控完成处置。'}`:(detail?.message||e?.message||'订单审核失败')}
async function approve(order:any){error.value='';message.value='';blockedOrder.value=null;try{await tradingApi.approve(order.id,'运营审核通过，Mock 执行');message.value='订单已审核通过并执行。';await load()}catch(e:any){error.value=riskBlockMessage(e);if((e?.response?.data?.detail?.code||e?.code)==='RISK_CONTROL_BLOCKED')blockedOrder.value=order}}async function reject(id:string){await tradingApi.reject(id,'工作人员审核拒绝');await load()}
onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">ORDER REVIEW</span><h2>订单审核</h2></div><span class="table-summary">待审核</span></div><p v-if="message" class="success">{{message}}</p><p v-if="error" class="error" aria-live="assertive">{{error}}</p><div v-if="blockedOrder" class="operation-restriction-note"><strong>该订单未执行。</strong><span>已生成或命中待处理风险预警，需由风控人员在“风险预警”工作台完成调查、要求补充资料、挂起/拒绝订单或作出有依据的结案后，才能继续审核。</span></div><div v-if="loading" class="empty">正在读取待审核订单…</div><div v-else class="module-table-wrap"><table class="admin-table"><thead><tr><th>订单号</th><th>客户</th><th>产品</th><th>金额</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td>{{order.order_no}}</td><td>{{order.user_id}}</td><td>{{order.product_name||order.product_id}}</td><td>¥{{order.amount}}</td><td>{{order.created_at}}</td><td><button class="table-action" @click="approve(order)">通过并执行</button><button class="table-action danger" @click="reject(order.id)">拒绝</button></td></tr><tr v-if="!orders.length"><td colspan="6" class="table-empty">暂无待审核订单</td></tr></tbody></table></div><PaginationBar :page="page" :page-size="pageSize" :total="total" @change="go" @size-change="changeSize"/></section></template>


